/* Shared styles for Section Configurations */
.section-config-container {
    min-height: 100%;
    flex: 1 0 auto;
    padding: 20px;
    background:
        linear-gradient(180deg, var(--primary-glow), var(--primary-glow) 220px),
        radial-gradient(circle at 80% 0%, rgba(6, 182, 212, 0.08), rgba(6, 182, 212, 0) 280px),
        var(--bg-void);
}

.section-modal-list-item {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 12px;
    border-bottom: 1px solid var(--border);
    cursor: pointer;
}

.section-modal-list-item:hover {
    background: var(--bg-card-hover);
}

.section-modal-list-item:last-child {
    border-bottom: none;
}

/* Enterprise configuration console primitives */
.config-console-shell {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.config-console-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 18px;
    padding: 14px 0 12px;
    border-bottom: 1px solid var(--border);
}

.config-console-heading {
    min-width: 0;
}

.config-console-title-row {
    display: flex;
    align-items: baseline;
    gap: 10px;
    flex-wrap: wrap;
}

.config-console-title {
    margin: 0;
    color: var(--text-main);
    font-size: 20px;
    font-weight: 700;
    line-height: 1.2;
}

.config-console-category {
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 600;
}

.config-console-category::before {
    content: "Â·";
    margin-right: 10px;
    color: var(--text-dim);
}

.config-console-meta {
    margin-top: 6px;
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.4;
}

.config-console-right {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 12px;
    flex-wrap: wrap;
}

.config-console-status,
.config-console-actions,
.config-table-actions {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.config-section-nav {
    display: flex;
    align-items: center;
    gap: 22px;
    min-height: 38px;
    border-bottom: 1px solid var(--border);
    overflow-x: auto;
    scrollbar-width: thin;
}

.config-section-nav-item {
    position: relative;
    height: 38px;
    padding: 0;
    border: 0;
    background: transparent;
    color: var(--text-muted);
    font: inherit;
    font-size: 13px;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
}

.config-section-nav-item:hover {
    color: var(--text-main);
}

.config-section-nav-item.is-active {
    color: var(--text-main);
}

.config-section-nav-item.is-active::after {
    content: "";
    position: absolute;
    right: 0;
    bottom: -1px;
    left: 0;
    height: 2px;
    background: var(--primary);
}

.config-console-content {
    min-width: 0;
}

.edge-config-stage {
    display: flex;
    flex-direction: column;
    gap: 18px;
    min-height: calc(100vh - 190px);
    padding: 22px 24px 24px;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.025), rgba(255, 255, 255, 0)),
        var(--bg-depth);
}

.edge-config-body {
    display: grid;
    gap: 16px;
}

.edge-config-stage .config-console-header {
    padding: 0 0 16px;
    flex: 0 0 auto;
}

.config-console-toggle.section-switch.section-switch-module {
    width: 58px;
    height: 26px;
}

.config-console-toggle.section-switch.section-switch-module .section-switch-slider {
    inset: 0;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    padding: 0 8px 0 26px;
    border-color: color-mix(in srgb, var(--border-strong, var(--border)) 88%, transparent);
    background: var(--bg-depth);
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.config-console-toggle.section-switch.section-switch-module .section-switch-slider::before {
    width: 18px;
    height: 18px;
    left: 3px;
    bottom: 3px;
    border-radius: 3px;
    background: color-mix(in srgb, var(--text-main) 86%, var(--bg-card));
    box-shadow: 0 1px 2px rgba(0, 0, 0, 0.28);
}

.config-console-toggle-label {
    color: var(--text-muted);
    font-size: 10px;
    font-weight: 700;
    letter-spacing: 0.04em;
    line-height: 1;
    text-transform: uppercase;
    transition: color 0.2s ease, opacity 0.2s ease;
}

.config-console-toggle.section-switch.section-switch-module input:checked + .section-switch-slider {
    border-color: color-mix(in srgb, var(--primary) 60%, var(--border));
    justify-content: flex-start;
    padding: 0 26px 0 8px;
    background: color-mix(in srgb, var(--primary) 86%, black 10%);
}

.config-console-toggle.section-switch.section-switch-module input:checked + .section-switch-slider::before {
    transform: translateX(31px);
    background: #ffffff;
}

.config-console-toggle.section-switch.section-switch-module input:checked + .section-switch-slider .config-console-toggle-label {
    color: #ffffff;
}

.edge-config-stage .config-section-nav {
    flex: 0 0 auto;
    margin-top: -6px;
}

.edge-config-stage .config-console-content {
    flex: 1 1 auto;
}

.edge-overview-summary {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(360px, 0.75fr);
    gap: 16px;
    padding: 18px 20px;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    background: var(--bg-card);
}

.edge-summary-main {
    display: flex;
    min-width: 0;
    flex-direction: column;
    justify-content: center;
    gap: 7px;
}

.edge-summary-label,
.edge-summary-metrics span {
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.edge-summary-main strong {
    color: var(--text-main);
    font-size: 24px;
    font-weight: 750;
    line-height: 1.1;
}

.edge-summary-main span:last-child {
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 550;
}

.edge-summary-metrics {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
}

.edge-summary-metrics div {
    display: flex;
    min-height: 62px;
    flex-direction: column;
    justify-content: center;
    gap: 7px;
    padding: 10px 12px;
    border: 1px solid var(--border);
    border-radius: var(--radius-sm);
    background: var(--bg-depth);
}

.edge-summary-metrics strong {
    color: var(--text-main);
    font-size: 16px;
    font-weight: 750;
}

.edge-operations-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 16px;
    align-items: stretch;
}

.edge-operations-grid .config-panel:first-child {
    grid-column: 1 / -1;
}

.edge-operations-grid .config-panel:first-child .config-panel-body {
    min-height: auto;
}

.edge-config-stage .config-panel {
    min-height: 100%;
    background: var(--bg-card);
}

.edge-config-stage .config-panel-body {
    display: flex;
    flex-direction: column;
    min-height: 280px;
}

.edge-engine-original {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: 16px;
}

.edge-engine-original .bot-overview-settings-grid {
    flex: 1;
    grid-template-columns: repeat(4, minmax(0, 1fr));
}

.edge-engine-original .bot-overview-setting-card {
    min-width: 0;
}

.edge-response-check {
    margin-top: 12px;
}

.edge-attack-section {
    display: flex;
    flex: 1;
    flex-direction: column;
    margin-top: 0;
}

.edge-quiet-empty {
    display: flex;
    flex: 1;
    min-height: 210px;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
    border: 1px dashed var(--border);
    border-radius: var(--radius);
    background: rgba(0, 0, 0, 0.08);
    text-align: center;
}

.edge-quiet-empty strong {
    color: var(--text-main);
    font-size: 14px;
}

.edge-quiet-empty span {
    max-width: 320px;
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.5;
}

.edge-config-stage .config-form-grid {
    align-items: end;
}

.edge-config-stage .config-action-row {
    margin-top: auto;
    padding-top: 16px;
    border-top: 1px solid var(--border);
}

.config-overview-stack,
.config-list-stack {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.config-metric-strip {
    display: grid;
    grid-template-columns: repeat(6, minmax(0, 1fr));
    border: 1px solid var(--border);
    border-radius: var(--radius);
    background: var(--bg-card);
    overflow: hidden;
}

.config-metric-item {
    min-width: 0;
    padding: 13px 14px;
    border-right: 1px solid var(--border);
}

.config-metric-item:last-child {
    border-right: 0;
}

.config-metric-value {
    color: var(--text-main);
    font-size: 20px;
    font-weight: 700;
    line-height: 1.15;
}

.config-metric-label {
    margin-top: 5px;
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 600;
}

.config-metric-item.tone-success .config-metric-value {
    color: var(--success);
}

.config-metric-item.tone-active .config-metric-value {
    color: var(--primary);
}

.config-metric-item.tone-warning .config-metric-value {
    color: var(--warning);
}

.config-metric-item.tone-danger .config-metric-value {
    color: var(--danger);
}

.config-panel-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 16px;
    align-items: start;
}

.config-panel,
.config-table-wrap {
    border: 1px solid var(--border);
    border-radius: var(--radius);
    background: var(--bg-card);
}

.config-panel-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    min-height: 46px;
    padding: 0 16px;
    border-bottom: 1px solid var(--border);
}

.config-panel-title {
    margin: 0;
    color: var(--text-main);
    font-size: 14px;
    font-weight: 700;
}

.config-panel-body {
    padding: 16px;
}

.config-kv-grid,
.config-compact-list {
    display: grid;
    gap: 0;
    border: 1px solid var(--border);
    border-radius: var(--radius);
    overflow: hidden;
}

.config-kv-row,
.config-compact-row {
    display: flex;
    justify-content: space-between;
    gap: 16px;
    padding: 10px 12px;
    border-bottom: 1px solid var(--border);
    color: var(--text-muted);
    font-size: 12px;
}

.config-kv-row:last-child,
.config-compact-row:last-child {
    border-bottom: 0;
}

.config-kv-row strong,
.config-compact-row strong {
    color: var(--text-main);
    font-weight: 700;
}

.config-subsection {
    margin-top: 16px;
}

.config-subsection-title {
    margin-bottom: 8px;
    color: var(--text-main);
    font-size: 12px;
    font-weight: 700;
}

.config-form-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.config-field,
.config-check-row {
    display: grid;
    gap: 7px;
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 600;
}

.config-check-row {
    grid-template-columns: auto 1fr;
    align-items: center;
    align-self: end;
    min-height: 38px;
}

.config-action-row {
    display: flex;
    justify-content: flex-end;
    margin-top: 14px;
}

.config-action-row .section-save-actions {
    margin: 0;
}

.config-status-pill {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: 20px;
    padding: 2px 8px;
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius-sm, 2px);
    background: var(--bg-card);
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 600;
    letter-spacing: 0.02em;
    line-height: 1.2;
    white-space: nowrap;
    text-shadow: none;
    box-sizing: border-box;
}

.config-status-pill.tone-success,
.config-status-pill.tone-active {
    background: var(--status-success-bg, rgba(89, 171, 143, 0.12)) !important;
    border-color: var(--status-success-border, rgba(89, 171, 143, 0.28)) !important;
    color: var(--slate-green, #59ab8f) !important;
}

.config-status-pill.tone-danger,
.config-status-pill.tone-error {
    background: rgba(239, 68, 68, 0.12) !important;
    border-color: rgba(239, 68, 68, 0.28) !important;
    color: #f87171 !important;
}

.config-status-pill.tone-warning {
    background: rgba(249, 115, 22, 0.12) !important;
    border-color: rgba(249, 115, 22, 0.28) !important;
    color: #fb923c !important;
}

.config-status-pill.tone-info {
    background: rgba(56, 189, 248, 0.12) !important;
    border-color: rgba(56, 189, 248, 0.28) !important;
    color: #38bdf8 !important;
}

.config-status-pill.tone-primary {
    background: rgba(249, 115, 22, 0.12) !important;
    border-color: rgba(249, 115, 22, 0.28) !important;
    color: #fb923c !important;
}

.config-status-pill.tone-neutral {
    background: rgba(255, 255, 255, 0.05) !important;
    border-color: rgba(255, 255, 255, 0.12) !important;
    color: #94a3b8 !important;
}

.config-console-status .config-status-pill {
    min-height: 26px;
    padding: 0 10px;
    border-radius: var(--radius-sm, 2px);
    background: transparent;
}

.config-console-status .config-status-pill.tone-danger {
    border-color: var(--status-neutral-border);
    background: var(--status-neutral-bg);
    color: var(--text-dim);
}

.config-console-status .config-status-pill.tone-warning {
    border-color: var(--status-neutral-border);
    background: var(--status-neutral-bg);
    color: var(--text-main);
}

.config-console-status .config-status-pill.tone-active {
    border-color: var(--status-neutral-border);
    background: var(--status-neutral-bg);
    color: var(--text-main);
}

.config-console-status .config-status-pill.tone-neutral {
    background: var(--status-neutral-bg);
    border-color: var(--status-neutral-border);
}

.config-toolbar {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
}

.config-toolbar-search {
    max-width: 320px;
}

.config-toolbar-select {
    max-width: 180px;
}

.config-toolbar-spacer {
    flex: 1 1 auto;
}

.config-toolbar-summary {
    display: flex;
    align-items: baseline;
    gap: 6px;
    color: var(--text-muted);
    font-size: 12px;
}

.config-toolbar-summary strong {
    color: var(--text-main);
}

.config-table-wrap {
    overflow-x: auto;
}

.config-enterprise-table {
    width: 100%;
    border-collapse: collapse;
    min-width: 760px;
}

.config-enterprise-table th,
.config-enterprise-table td {
    padding: 11px 14px;
    border-bottom: 1px solid var(--border);
    text-align: left;
    vertical-align: middle;
}

.config-enterprise-table th {
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 700;
    background: var(--bg-depth);
}

.config-enterprise-table tr:last-child td {
    border-bottom: 0;
}

.security-events-routing-table-wrap {
    max-width: 100%;
}

.security-events-routing-table {
    min-width: 1120px;
    table-layout: fixed;
}

.security-events-routing-table th:nth-child(1) { width: 142px; }
.security-events-routing-table th:nth-child(2) { width: 76px; }
.security-events-routing-table th:nth-child(3) { width: 24%; }
.security-events-routing-table th:nth-child(4) { width: 24%; }
.security-events-routing-table th:nth-child(5) { width: 148px; }
.security-events-routing-table th:nth-child(6) { width: 170px; }
.security-events-routing-table th:nth-child(7) { width: 96px; }
.security-events-routing-table th:nth-child(8) { width: 64px; }

.security-events-routing-table td {
    white-space: nowrap;
}

.security-events-routing-table .security-events-status {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    color: var(--text-secondary);
    font-size: 12px;
    line-height: 1.25;
    white-space: nowrap;
}

.security-events-routing-table .security-events-status strong {
    color: var(--text-main);
    font-size: 12px;
    font-variant-numeric: tabular-nums;
    font-weight: 700;
}

.security-events-routing-table .security-events-status.is-error,
.security-events-routing-table .security-events-status.is-error strong {
    color: var(--brand-orange);
}

[data-theme="dark"] .security-events-routing-table .security-events-status.is-error,
[data-theme="dark"] .security-events-routing-table .security-events-status.is-error strong {
    color: #edaa7b;
}

.security-events-routing-table .waf-dashboard-request > span,
.security-events-routing-table .waf-dashboard-rule > span,
.security-events-routing-source > span {
    display: block;
    overflow: hidden;
    text-overflow: ellipsis;
}

.security-events-pagination {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 14px;
    padding: 12px 14px;
    border-top: 1px solid var(--border);
    color: var(--text-muted);
    font-size: 12px;
}

.security-events-pagination-controls {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
}

.security-events-pagination-page {
    min-width: 46px;
    color: var(--text-secondary);
    text-align: center;
}

.security-events-page-size-label {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin-left: 6px;
    white-space: nowrap;
}

.security-events-page-size {
    min-width: 64px;
    height: 30px;
    padding: 0 26px 0 8px;
    border: 1px solid var(--border);
    border-radius: 4px;
    background: var(--bg-card);
    color: var(--text-main);
    font: inherit;
}

@media (max-width: 720px) {
    .security-events-pagination {
        align-items: flex-start;
        flex-direction: column;
    }

    .security-events-pagination-controls {
        flex-wrap: wrap;
    }
}

.config-table-primary {
    color: var(--text-main);
    font-size: 13px;
    font-weight: 650;
}

.config-table-sub {
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.45;
}

.config-table-code {
    display: block;
    max-width: 440px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-family: var(--font-main);
}

.config-table-empty-cell {
    padding: 24px !important;
}

.config-table-empty-cell .empty-state {
    padding: 12px;
}

.config-table-empty-cell .empty-state-icon {
    display: none;
}

.config-table-empty-cell .empty-state h3 {
    margin: 0 0 6px;
    font-size: 14px;
}

.config-table-empty-cell .empty-state p {
    margin: 0;
    color: var(--text-muted);
    font-size: 12px;
}

@media (max-width: 960px) {
    .config-console-header,
    .config-console-right {
        align-items: flex-start;
        flex-direction: column;
    }

    .config-metric-strip,
    .config-panel-grid,
    .config-form-grid,
    .edge-overview-summary,
    .edge-operations-grid {
        grid-template-columns: 1fr;
    }

    .firewall-overview-shell .edge-firewall-controls .bot-overview-settings-grid,
    .firewall-overview-shell .firewall-threat-snapshot .bot-overview-settings-grid {
        grid-template-columns: 1fr;
    }

    .edge-choice-row,
    .edge-level-grid,
    .edge-rules-grid {
        grid-template-columns: 1fr;
    }

    .config-metric-item {
        border-right: 0;
        border-bottom: 1px solid var(--border);
    }

    .config-metric-item:last-child {
        border-bottom: 0;
    }
}

/* Enterprise configuration page header */
.config-page-hero {
    margin-bottom: 20px;
    padding: 18px 20px;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background:
        linear-gradient(180deg, var(--glass-highlight), var(--glass-highlight)),
        linear-gradient(90deg, var(--primary-glow), rgba(6, 182, 212, 0.035) 46%, var(--glass-highlight) 100%),
        var(--bg-card);
    box-shadow: inset 0 1px 0 var(--glass-highlight), var(--shadow-sm);
}

.config-page-hero-main {
    min-width: 0;
    max-width: 760px;
}

.config-page-hero-bar {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
}

.config-page-hero-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
    margin-left: auto;
}

.config-page-hero-kicker {
    margin-bottom: 7px;
    color: var(--secondary);
    font-size: 11px;
    font-weight: 700;
    line-height: 1;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.config-page-hero-title {
    margin: 0;
    color: var(--text-main);
    font-size: 22px;
    font-weight: 700;
    line-height: 1.2;
}

.config-page-hero-subtitle {
    max-width: 720px;
    margin: 8px 0 0;
    color: var(--text-muted);
    font-size: 13px;
    line-height: 1.55;
}

/* Shared section navigation primitives */
.section-tab-row {
    display: flex;
    align-items: center;
    gap: 4px;
    margin-bottom: 18px;
    padding: 5px;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: linear-gradient(180deg, var(--glass-highlight), var(--glass-highlight)), var(--bg-depth);
    box-shadow: inset 0 1px 0 var(--glass-highlight), var(--shadow-xs);
    overflow-x: auto;
    scrollbar-width: thin;
    scrollbar-color: var(--border-strong) transparent;
}

.section-tab-btn::before,
.section-tab-btn::after {
    display: none !important;
}

.section-tab-btn.btn-primary,
.section-tab-btn.active,
.section-tab-btn.is-active {
    background: linear-gradient(180deg, var(--primary-dim), var(--primary-dim)) !important;
    border-color: var(--primary-dim) !important;
    color: var(--bg-card) !important;
}

.section-tab-btn.btn-primary svg,
.section-tab-btn.active svg,
.section-tab-btn.is-active svg {
    color: var(--secondary);
    opacity: 1;
}

/* Shared section hero/header primitives */
.section-hero-shell {
    margin-bottom: 24px;
}

.section-hero-split {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 16px;
}

.section-hero-main {
    display: flex;
    align-items: center;
    gap: 16px;
}

.section-hero-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--radius-lg);
}

.section-hero-body {
    flex: 1;
    min-width: 0;
}

.section-hero-title {
    font-size: 16px;
    font-weight: 600;
    color: var(--text);
}

.section-hero-sub {
    font-size: 13px;
    color: var(--text-muted);
}

/* Shared section status bar primitives */
.section-status-bar {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 18px;
    background: var(--bg-depth);
    border-radius: var(--radius-lg);
    margin-bottom: 24px;
}

.section-status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--text-dim);
}

.section-status-dot.is-success {
    background: var(--success);
}

.section-status-dot.is-danger {
    background: var(--danger);
}

.section-status-title {
    font-weight: 600;
    font-size: 14px;
    color: var(--text);
}

.section-status-divider {
    color: var(--text-dim);
}

.section-status-meta {
    color: var(--text-muted);
    font-size: 13px;
}

.section-status-right {
    margin-left: auto;
    display: flex;
    align-items: center;
    gap: 12px;
}

.section-status-label {
    font-size: 12px;
    color: var(--text-dim);
    text-transform: uppercase;
    font-weight: 600;
}

/* Shared overview metric primitives */
.section-metric-card {
    background: var(--bg-depth);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    padding: 16px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
}

.section-metric-card-wide {
    padding: 16px 20px;
}

.section-metric-label {
    font-size: 11px;
    text-transform: uppercase;
    color: var(--text-dim);
    font-weight: 600;
    letter-spacing: 1px;
    margin-bottom: 4px;
}

.section-metric-value {
    font-size: 18px;
    font-weight: 600;
    color: var(--text-main);
    font-family: var(--font-main);
}

.section-metric-unit {
    font-size: 12px;
    color: var(--text-muted);
    margin-left: 2px;
    font-family: inherit;
    font-weight: 500;
}

.section-metric-icon {
    opacity: 0.8;
    display: inline-flex;
}

.section-metric-icon.tone-primary {
    color: var(--primary);
}

.section-metric-icon.tone-info {
    color: var(--info);
}

.section-metric-icon.tone-success {
    color: var(--success);
}

.section-metric-icon.tone-warning {
    color: var(--warning);
}

.section-metric-icon.tone-danger {
    color: var(--danger);
}

/* Shared feature/module card primitives */
.section-feature-card {
    display: block;
    padding: 12px 16px;
    cursor: pointer;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    transition: all 0.2s ease;
}

.section-feature-card.is-readonly {
    cursor: default;
}

.section-feature-card.tone-primary {
    --section-feature-accent: var(--primary);
}

.section-feature-card.tone-info {
    --section-feature-accent: var(--info);
}

.section-feature-card.tone-success {
    --section-feature-accent: var(--success);
}

.section-feature-card.tone-warning {
    --section-feature-accent: var(--warning);
}

.section-feature-card.tone-danger {
    --section-feature-accent: var(--danger);
}

.section-feature-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 8px;
}

.section-feature-row-start {
    align-items: flex-start;
}

.section-feature-main {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.section-feature-icon {
    width: 32px;
    height: 32px;
    border-radius: var(--radius-lg);
    background: var(--bg-elevated);
    color: var(--text-muted);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.section-feature-title {
    font-size: 13px;
    display: block;
    color: var(--text-main);
    font-weight: 600;
}

.section-feature-desc {
    font-size: 11px;
    color: var(--text-muted);
    display: block;
    line-height: 1.4;
}

.section-feature-indicator {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 2px solid var(--border);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.section-feature-card.is-active .section-feature-indicator {
    border-color: var(--section-feature-accent, var(--success));
}

.section-feature-indicator-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--section-feature-accent, var(--success));
}

.section-feature-row-start {
    align-items: flex-start;
}

.section-feature-icon-sm {
    width: 28px;
    height: 28px;
    border-radius: var(--radius);
}

/* Shared section layout shells */
.section-panel-stack {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.section-tabs-wrap {
    align-items: center;
    flex-wrap: nowrap;
}

.section-tabs-wrap .btn {
    min-height: 38px;
}

.section-page-card {
    overflow: visible;
    padding: 20px;
    background:
        linear-gradient(180deg, var(--glass-highlight), var(--glass-highlight)),
        var(--bg-card);
    border-color: var(--border);
}

.section-console-shell {
    display: flex;
    flex-direction: column;
    gap: 14px;
}

.section-console-summary {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    padding: 2px 0 14px;
    background: transparent;
    border: 0;
    border-bottom: 1px solid var(--border);
    border-radius: 0;
}

.section-console-main,
.section-console-actions {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.section-console-title {
    font-size: 14px;
    font-weight: 750;
    color: var(--text-main);
}

.section-console-sub {
    margin-top: 2px;
    color: var(--text-muted);
    font-size: 12px;
}

.section-console-layout {
    display: grid;
    grid-template-columns: 220px minmax(0, 1fr);
    gap: 16px;
    align-items: start;
}

.section-console-rail {
    background: transparent;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    overflow: hidden;
}

.section-console-nav {
    width: 100%;
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 12px 14px;
    border: 0;
    border-left: 3px solid transparent;
    background: transparent;
    color: var(--text-muted);
    text-align: left;
    cursor: pointer;
}

.section-console-nav:hover {
    background: var(--bg-depth);
}

.section-console-nav.is-active {
    background: color-mix(in srgb, var(--primary) 8%, transparent);
    border-left-color: var(--primary);
    color: var(--text-main);
}

.section-console-nav-icon {
    width: 18px;
    display: inline-flex;
    justify-content: center;
    color: var(--primary);
}

.section-console-nav-copy {
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.section-console-nav-title {
    font-size: 13px;
    font-weight: 650;
    color: var(--text-main);
}

.section-console-nav-desc {
    margin-top: 2px;
    font-size: 11px;
    color: var(--text-dim);
    font-family: var(--font-main);
}

.section-console-workspace {
    min-width: 0;
    padding: 0 0 16px;
}

.section-workspace-head {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
    padding-bottom: 14px;
    margin-bottom: 14px;
    border-bottom: 1px solid var(--border);
}

.section-workspace-kicker {
    font-size: 10px;
    font-weight: 800;
    color: var(--text-muted);
    text-transform: uppercase;
    letter-spacing: 0;
}

.section-workspace-title {
    margin: 2px 0 0;
    color: var(--text-main);
    font-size: 20px;
    line-height: 1.2;
}

.section-workspace-sub {
    margin: 4px 0 0;
    color: var(--text-muted);
    font-size: 13px;
}

.section-workspace-actions {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    justify-content: flex-end;
}

.section-kpi-strip {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(96px, 1fr));
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    margin-bottom: 16px;
}

.section-kpi-strip .section-overview-stat {
    border: 0;
    border-radius: 0;
    border-right: 1px solid var(--border);
    background: var(--bg-card);
    text-align: left;
    padding: 12px 14px;
}

.section-kpi-strip .section-overview-stat:last-child {
    border-right: 0;
}

.section-kpi-strip .section-overview-stat-value {
    font-size: 20px;
    margin-bottom: 2px;
}

.section-flat-grid {
    display: flex;
    flex-direction: column;
    gap: 0;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    overflow: hidden;
    background: var(--bg-card);
    margin-bottom: 16px;
}

.section-flat-grid-4 {
    grid-template-columns: 1fr;
}

.section-flat-grid-2 {
    grid-template-columns: 1fr;
}

.section-flat-link {
    min-height: 74px;
    display: grid;
    grid-template-columns: 28px minmax(0, 1fr) auto;
    align-items: center;
    gap: 10px;
    padding: 11px 12px;
    border: 0;
    border-bottom: 1px solid var(--border);
    border-radius: 0;
    background: transparent;
    cursor: pointer;
}

.section-flat-link:hover {
    background: var(--bg-depth);
}

.section-flat-link.is-active {
    background: color-mix(in srgb, var(--primary) 7%, transparent);
}

.section-flat-link:last-child {
    border-bottom: 0;
}

.section-flat-link-icon {
    color: var(--primary);
    display: inline-flex;
}

.section-flat-link-title {
    font-size: 13px;
    font-weight: 700;
    color: var(--text-main);
}

.section-flat-link-desc {
    margin-top: 3px;
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.35;
}

.section-flat-link-state {
    color: var(--text-dim);
    font-size: 11px;
    font-family: var(--font-main);
    text-transform: uppercase;
}

.section-console-edit-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(320px, 0.7fr);
    gap: 14px;
    align-items: start;
}

.section-flat-panel {
    padding: 14px 0 0;
    background: transparent;
    border: 0;
    border-top: 1px solid var(--border);
    border-radius: 0;
}

.section-table-panel {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    overflow: hidden;
}

@media (max-width: 1100px) {
    .section-console-layout {
        grid-template-columns: 1fr;
    }

    .section-console-rail {
        display: grid;
        grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    }

    .section-console-nav {
        border-left: 0;
        border-bottom: 3px solid transparent;
    }

    .section-console-nav.is-active {
        border-left-color: transparent;
        border-bottom-color: var(--primary);
    }

    .section-console-edit-grid {
        grid-template-columns: 1fr;
    }
}

.section-status-bar {
    border: 1px solid var(--border);
}

.section-overview-grid {
    display: grid;
    grid-template-columns: minmax(220px, 280px) minmax(0, 1fr);
    gap: 16px;
    align-items: stretch;
}

.section-health-card {
    min-height: 176px;
    padding: 24px;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: var(--bg-depth);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
}

.section-stats-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 12px;
}

.section-stats-grid .section-metric-card {
    min-height: 82px;
}

.section-module-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 12px;
}

.section-feature-card {
    background: var(--bg-depth);
}

.section-feature-card:hover {
    border-color: var(--border-strong);
    background: linear-gradient(180deg, var(--glass-highlight), var(--glass-highlight)), var(--bg-card-hover);
}

.section-feature-card.is-active {
    border-color: var(--primary);
    background: linear-gradient(180deg, var(--primary-glow), var(--primary-glow)), var(--bg-depth);
    box-shadow: inset 0 1px 0 var(--glass-highlight);
}

.section-feature-card[data-waf-action],
.section-feature-card[data-traffic-action],
.section-feature-card[data-httpsec-action],
.section-feature-card[data-access-action],
.section-feature-card[data-api-security-action],
.section-feature-card[data-antibot-action] {
    cursor: pointer;
}

.section-config-card {
    margin-bottom: 16px;
    padding: 0;
    overflow: hidden;
    border-left: 0;
}

.section-config-card:hover {
    background: var(--bg-card);
}

.section-config-card .feature-header {
    padding: 16px 18px;
    border-bottom: 1px solid var(--border);
    background: var(--bg-depth);
}

.section-config-card.active .feature-header {
    border-bottom-color: var(--primary-dim);
}

.section-config-card>.mt-16,
.section-config-card>.mt-20,
.section-config-card>.grid-2 {
    padding: 18px;
    margin-top: 0;
}

.feature-icon {
    width: 40px;
    height: 40px;
    padding: 0;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.feature-status {
    min-width: 56px;
    text-align: right;
}

.gauge-track {
    height: 6px;
    overflow: hidden;
    border-radius: 999px;
    background: var(--bg-elevated);
}

.gauge-fill {
    width: var(--pct, 0%);
    height: 100%;
    border-radius: inherit;
    background: var(--success);
}

.gauge-fill.tone-warning {
    background: var(--warning);
}

.gauge-fill.tone-danger {
    background: var(--danger);
}

.section-choice-icon {
    width: 32px;
    height: 32px;
    border-radius: var(--radius-lg);
    background: var(--bg-elevated);
    color: var(--text-muted);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

[data-httpsec-action].border-primary .section-choice-icon,
.tile.border-primary .section-choice-icon {
    color: var(--primary);
    background: var(--primary-glow);
}

.feature-header {
    gap: 12px;
    flex-wrap: wrap;
}

.feature-meta {
    min-width: 0;
    flex: 1;
}

.feature-meta>div:last-child {
    min-width: 0;
}

.feature-meta p {
    word-break: break-word;
}

.module-card-compact {
    min-height: 88px;
}

.module-card-body {
    align-items: flex-start;
}

.modules-dashboard-shell,
.module-config-shell {
    width: 100%;
    max-width: none;
}

.module-console-shell {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.module-console-hero {
    margin-bottom: 0;
}

.module-console-summary {
    display: grid;
    min-width: 360px;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
}

.module-summary-pill {
    padding: 10px 12px;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: var(--bg-depth);
}

.module-summary-pill span {
    display: block;
    margin-bottom: 5px;
    color: var(--text-dim);
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
}

.module-summary-pill strong {
    display: block;
    color: var(--text-main);
    font-size: 20px;
    line-height: 1;
}

.module-summary-pill.success strong {
    color: var(--text-main);
}

.module-summary-pill.primary strong {
    color: var(--text-main);
}

.module-console-layout {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 300px;
    gap: 16px;
    align-items: start;
}

.module-widgets-section {
    width: 100%;
}

.module-widgets-grid {
    grid-template-columns: repeat(3, minmax(300px, 1fr));
    gap: 16px;
}

.module-widget-restored {
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
    align-items: stretch;
    gap: 16px;
    min-height: 300px;
    aspect-ratio: 1.05 / 1;
    border-radius: var(--radius-lg);
    text-align: center;
    padding: 22px;
    overflow: hidden;
}

.module-widget-restored::before {
    content: "";
    position: absolute;
    inset: 1px;
    border-radius: inherit;
    pointer-events: none;
    background:
        radial-gradient(circle at 50% 34%, color-mix(in srgb, var(--text-main) 7%, transparent), transparent 28%),
        linear-gradient(180deg, color-mix(in srgb, var(--bg-elevated) 46%, transparent), transparent 52%);
    opacity: 0.45;
}

.module-widget-restored > div:first-child {
    position: relative;
    z-index: 1;
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 18px 0 20px;
}

.module-widget-restored .module-widget-icon {
    width: 92px;
    height: 92px;
    color: var(--text-muted);
    background: color-mix(in srgb, var(--bg-depth) 82%, black);
    border: 1px solid var(--border-strong);
    border-radius: 999px;
    box-shadow: inset 0 1px 0 var(--glass-highlight), 0 12px 28px color-mix(in srgb, black 24%, transparent);
    transition: transform 0.18s ease, border-color 0.18s ease, color 0.18s ease;
}

.module-widget-restored .module-widget-icon svg {
    width: 40px;
    height: 40px;
}

.module-widget-restored:hover .module-widget-icon {
    transform: translateY(-2px);
    color: var(--text-main);
    border-color: var(--border-strong);
}

.module-widget-restored .module-widget-header {
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 16px;
    min-height: 0;
    margin-bottom: 0;
    transform: none;
}

.module-widget-restored .module-widget-info h4 {
    font-size: 18px;
    line-height: 1.2;
}

.module-widget-restored .module-widget-desc {
    max-width: 280px;
    min-height: 0;
    margin: 14px auto 0;
    text-align: center;
}

.module-widget-restored .module-widget-footer {
    width: 100%;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    padding-top: 14px;
    margin-top: auto;
    border-top: 1px solid var(--border);
    position: relative;
    z-index: 1;
}

.module-widget-restored .module-widget-status,
.module-widget-restored .module-widget-actions {
    justify-content: center;
}

.module-widget-restored .module-widget-actions {
    flex-direction: row;
    gap: 12px;
}

.module-widget-restored.module-locked {
    pointer-events: auto;
}

.module-widget-metric {
    margin-left: 0;
}

.module-header-switch {
    flex: 0 0 auto;
}

.module-registry-panel,
.module-side-panel,
.module-config-panel {
    padding: 18px;
}

.module-panel-header {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 14px;
    margin-bottom: 14px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--border);
}

.module-panel-header h3,
.module-side-panel h3 {
    margin: 0;
    color: var(--text-main);
    font-size: 15px;
    font-weight: 700;
}

.module-panel-header p,
.module-side-panel p {
    margin: 5px 0 0;
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.45;
}

.module-panel-count {
    color: var(--text-dim);
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    white-space: nowrap;
}

.module-registry-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.module-registry-row {
    display: grid;
    grid-template-columns: 38px minmax(0, 1fr) 128px auto;
    gap: 12px;
    align-items: center;
    min-height: 76px;
    padding: 12px;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: var(--bg-depth);
}

.module-registry-row.is-active {
    border-color: var(--border-strong);
}

.module-registry-row.is-disabled {
    opacity: 0.68;
}

.module-registry-icon {
    width: 38px;
    height: 38px;
    border-radius: var(--radius-lg);
    background: var(--bg-elevated);
    color: var(--text-muted);
    display: inline-flex;
    align-items: center;
    justify-content: center;
}

.module-registry-main {
    min-width: 0;
}

.module-registry-title-row {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 10px;
}

.module-registry-status {
    display: inline-flex;
    align-items: center;
    min-height: 20px;
    padding: 2px 7px;
    border: 1px solid var(--border);
    border-radius: 999px;
    font-size: 10px;
    font-weight: 700;
    line-height: 1;
    text-transform: uppercase;
    white-space: nowrap;
}

.module-registry-status.success {
    color: var(--success);
    border-color: var(--status-success-border);
    background: var(--status-success-bg);
}

.module-registry-status.warning {
    color: var(--warning);
    border-color: var(--status-warning-border);
    background: var(--status-warning-bg);
}

.module-registry-meta {
    color: var(--text-dim);
    font-size: 11px;
    line-height: 1.35;
}

.module-registry-meta span,
.module-registry-meta strong {
    display: block;
}

.module-registry-meta strong {
    margin-top: 3px;
    color: var(--text-muted);
    font-weight: 600;
}

.module-registry-actions {
    display: flex;
    justify-content: flex-end;
}

.module-map-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 16px;
}

.module-map-item {
    padding: 12px;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: var(--bg-depth);
}

.module-map-item span,
.module-map-item strong {
    display: block;
}

.module-map-item span {
    color: var(--text-main);
    font-size: 12px;
    font-weight: 700;
}

.module-map-item strong {
    margin-top: 5px;
    color: var(--text-muted);
    font-size: 12px;
    font-weight: 500;
    line-height: 1.45;
}

.module-config-shell {
    display: flex;
    flex-direction: column;
    gap: 16px;
}

.module-config-panel-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(280px, 360px);
    gap: 16px;
    align-items: start;
}

.challenge-preview-layout {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-items: stretch;
}

.challenge-preview-layout > aside {
    display: flex;
    min-width: 0;
}

.challenge-preview-card {
    display: flex;
    flex-direction: column;
    width: 100%;
    height: 100%;
}

.challenge-preview-card .preview-box {
    flex: 1 1 auto;
    min-height: 0;
    aspect-ratio: auto;
}

.challenge-preview-card .preview-inner {
    max-width: 430px;
    padding: 34px;
}

.challenge-preview-card .spinner-preview {
    width: 42px;
    height: 42px;
    margin-bottom: 20px;
}

.challenge-preview-card .preview-footer {
    bottom: 18px;
    font-size: 11px;
}

.challenge-preview-card .preview-empty {
    background: var(--bg-depth);
    border-style: dashed;
}

.preview-empty-state {
    max-width: 360px;
    display: flex;
    flex-direction: column;
    gap: 8px;
    align-items: center;
    justify-content: center;
    padding: 24px;
    text-align: center;
}

.preview-empty-state strong {
    color: var(--text-main);
    font-size: 14px;
    font-weight: 700;
}

.preview-empty-state span {
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.45;
}

.module-provider-grid {
    display: grid;
    grid-template-columns: repeat(5, minmax(0, 1fr));
    gap: 8px;
}

.module-provider-card {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    min-height: 82px;
    padding: 12px;
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    background: var(--bg-depth);
    cursor: pointer;
}

.module-provider-card:hover {
    border-color: var(--border-strong);
    background: var(--bg-card-hover);
}

.module-provider-card.is-active {
    border-color: var(--primary);
    background: var(--primary-glow);
}

.module-provider-card input {
    margin-top: 2px;
}

.module-provider-card span,
.module-provider-card strong,
.module-provider-card small {
    display: block;
}

.module-provider-card strong {
    color: var(--text-main);
    font-size: 12px;
    font-weight: 700;
    line-height: 1.25;
}

.module-provider-card small {
    margin-top: 4px;
    color: var(--text-muted);
    font-size: 11px;
    line-height: 1.35;
}

.provider-favicon-local {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--primary);
    background: var(--primary-glow);
    font-size: 10px;
    font-weight: 800;
    line-height: 1;
}

.module-old-shell {
    width: 100%;
    display: grid;
    gap: 16px;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
}

.module-old-header,
.module-old-card {
    border-radius: var(--radius);
    background: var(--bg-card);
    border-color: var(--border);
    box-shadow: none;
}

.module-old-header {
    margin-bottom: 0;
    padding: 20px 22px;
}

.module-old-card {
    padding: 22px;
}

.module-old-card .settings-section-title {
    margin: 0 0 16px;
    padding: 0 0 12px;
    border-bottom: 1px solid var(--border);
    color: var(--text-main);
    font-size: 14px;
    letter-spacing: 0;
    text-transform: none;
}

.module-old-card .settings-section-title small {
    margin-left: auto;
    color: var(--text-dim);
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0;
    text-transform: none;
}

.captcha-module-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 20px;
}

.captcha-module-heading {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 14px;
}

.captcha-module-icon {
    width: 42px;
    height: 42px;
    padding: 0;
    border: 1px solid color-mix(in srgb, var(--primary) 42%, var(--border));
    border-radius: var(--radius);
    background: color-mix(in srgb, var(--primary) 8%, var(--bg-depth));
}

.captcha-module-icon svg {
    width: 22px;
    height: 22px;
}

.captcha-module-title {
    display: grid;
    min-width: 0;
    gap: 4px;
}

.captcha-module-kicker {
    color: var(--primary);
    font-size: 10px;
    font-weight: 750;
    letter-spacing: 0.1em;
}

.captcha-module-title h4 {
    margin: 0;
    color: var(--text-main);
    font-size: 18px;
}

.captcha-module-title p {
    margin: 0;
    color: var(--text-muted);
    font-size: 12px;
}

.captcha-module-status {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    flex: 0 0 auto;
    color: var(--text-muted);
    font-size: 11px;
    font-weight: 650;
}

.captcha-module-status span {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--status-success, #2fbf71);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--status-success, #2fbf71) 15%, transparent);
}

.captcha-provider-grid {
    align-items: stretch;
}

.module-choice-tile {
    min-height: 74px;
    border-radius: var(--radius-lg);
    background: var(--bg-depth);
}

.captcha-provider-tile {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    justify-content: space-between;
    gap: 12px;
    min-height: 82px;
    padding: 14px 16px;
    background: var(--bg-depth);
    border-width: 2px;
    cursor: pointer;
    transition: border-color 140ms ease, background-color 140ms ease, box-shadow 140ms ease;
}

.captcha-provider-card-main {
    display: flex;
    min-width: 0;
    align-items: center;
    gap: 12px;
}

.captcha-provider-tile:hover {
    border-color: color-mix(in srgb, var(--primary) 55%, var(--border));
    background: var(--bg-elevated);
}

.captcha-provider-tile:focus-within {
    outline: 2px solid color-mix(in srgb, var(--primary) 55%, transparent);
    outline-offset: 2px;
}

.captcha-provider-logo {
    width: 40px;
    height: 40px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex: 0 0 40px;
    border-radius: var(--radius);
    background: var(--bg-depth);
    border: 1px solid var(--border);
}

.captcha-provider-logo svg {
    width: 30px;
    height: 30px;
    display: block;
}

.captcha-provider-copy {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.captcha-provider-copy strong {
    overflow: hidden;
    color: var(--text-main);
    font-size: 13px;
    font-weight: 700;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.captcha-provider-copy small {
    overflow: hidden;
    color: var(--text-muted);
    font-size: 11px;
    line-height: 1.3;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.captcha-provider-card-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    margin-top: 13px;
    padding-top: 10px;
    border-top: 1px solid color-mix(in srgb, var(--border) 78%, transparent);
    color: var(--text-dim);
    font-size: 10px;
    font-weight: 650;
}

.captcha-provider-card-footer svg {
    width: 14px;
    height: 14px;
    fill: none;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;
    transition: transform 140ms ease;
}

.captcha-provider-tile:hover .captcha-provider-card-footer svg {
    transform: translateX(2px);
}

.captcha-provider-tile.active .captcha-provider-card-footer {
    color: var(--primary);
}

.captcha-credentials-divider {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    margin-top: 22px;
    padding-top: 18px;
    border-top: 1px solid var(--border);
}

.captcha-credentials-divider > div {
    display: grid;
    gap: 4px;
}

.captcha-credentials-divider strong {
    color: var(--text-main);
    font-size: 13px;
    font-weight: 700;
}

.captcha-credentials-divider span {
    color: var(--text-muted);
    font-size: 11px;
}

.captcha-credentials-grid {
    margin-top: 16px;
}

.captcha-provider-tile.active .captcha-provider-logo {
    border-color: var(--primary);
    background: color-mix(in srgb, var(--primary) 10%, var(--bg-depth));
}

.captcha-provider-tile.active {
    border-color: var(--primary);
    background: var(--bg-elevated);
    box-shadow: inset 3px 0 0 var(--primary);
}

.challenge-old-grid {
    align-items: start;
}

.challenge-old-preview-card .preview-box {
    min-height: 300px;
}

.challenge-old-preview-card .preview-inner {
    max-width: 390px;
}

@media (max-width: 1180px) {
    .module-console-layout,
    .module-config-panel-grid,
    .challenge-preview-layout,
    .challenge-old-grid {
        grid-template-columns: 1fr;
    }

    .module-console-summary {
        min-width: 0;
        width: 100%;
    }

    .challenge-preview-card .preview-box {
        min-height: 340px;
    }

    .module-provider-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

[data-theme="light"] .config-list-stack {
    display: grid;
    gap: 14px;
}

[data-theme="light"] .config-toolbar {
    min-height: 54px;
    padding: 10px 12px;
    border: 1px solid #dedfe3;
