    align-items: center;
    gap: 7px;
    min-height: 28px;
    padding: 0 8px;
    color: var(--text-main);
    background: var(--bg-depth);
    border: 1px solid var(--border);
    border-radius: 6px;
    font-family: var(--font-main);
    font-size: 12px;
    cursor: pointer;
}

.httpsec-extension-chip:hover {
    background: var(--surface-subtle, rgba(148, 163, 184, 0.08));
    border-color: var(--text-muted);
}

.httpsec-extension-remove {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 15px;
    height: 15px;
    border-radius: 4px;
    color: var(--text-muted);
    background: transparent;
    font-family: var(--font-sans);
    font-size: 13px;
    line-height: 1;
}

.httpsec-empty-note {
    width: 100%;
    padding: 10px 12px;
    color: var(--text-muted);
    background: var(--bg-depth);
    border: 1px dashed var(--border);
    border-radius: var(--radius);
    font-size: 12px;
}

.httpsec-check-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 7px;
}

.httpsec-check-tile {
    display: flex;
    align-items: center;
    gap: 7px;
    min-height: 32px;
    padding: 6px 8px;
    color: var(--text-main);
    background: var(--bg-depth);
    border: 1px solid var(--border);
    border-radius: 6px;
    font-family: var(--font-main);
    font-size: 12px;
    cursor: pointer;
}

.httpsec-check-tile input {
    width: 14px;
    height: 14px;
    margin: 0;
    accent-color: var(--primary);
}

.httpsec-check-tile.is-active {
    color: var(--primary);
    border-color: color-mix(in srgb, var(--primary) 45%, var(--border));
    background: color-mix(in srgb, var(--primary) 9%, var(--bg-depth));
}

.httpsec-method-grid-blocklist .httpsec-check-tile.is-active {
    color: var(--danger);
    border-color: color-mix(in srgb, var(--danger) 45%, var(--border));
    background: color-mix(in srgb, var(--danger) 10%, var(--bg-depth));
}

.httpsec-method-grid-blocklist .httpsec-check-tile input {
    accent-color: var(--danger);
}

.httpsec-method-grid-allowlist .httpsec-check-tile.is-active {
    color: var(--success);
    border-color: color-mix(in srgb, var(--success) 45%, var(--border));
    background: color-mix(in srgb, var(--success) 10%, var(--bg-depth));
}

.httpsec-method-grid-allowlist .httpsec-check-tile input {
    accent-color: var(--success);
}

.httpsec-response-groups {
    display: grid;
    gap: 16px;
}

.httpsec-response-group {
    display: grid;
    gap: 10px;
}

.httpsec-response-group-head {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 14px;
    padding: 0 2px;
}

.httpsec-response-group-head h3 {
    margin: 0;
    color: var(--text-main);
    font-size: 13px;
    font-weight: 800;
    text-transform: uppercase;
}

.httpsec-response-group-head span {
    color: var(--text-muted);
    font-size: 12px;
}

.httpsec-simple-stack {
    display: grid;
    gap: 12px;
    margin-top: 16px;
}

.httpsec-simple-row {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(220px, auto);
    gap: 16px;
    align-items: center;
    padding: 12px;
    background: var(--bg-depth);
    border: 1px solid var(--border);
    border-radius: 8px;
}

.httpsec-simple-row .section-segment-row {
    justify-content: flex-end;
}

.httpsec-simple-select {
    width: 260px;
    justify-self: end;
}

.httpsec-advanced-details {
    clear: both;
    margin-top: 14px;
    padding: 12px;
    background: color-mix(in srgb, var(--bg-depth) 60%, transparent);
    border: 1px solid var(--border);
    border-radius: 8px;
}

.httpsec-advanced-details summary {
    color: var(--text-main);
    font-size: 12px;
    font-weight: 700;
    cursor: pointer;
}

.httpsec-advanced-details summary::marker {
    color: var(--text-muted);
}

.httpsec-choice-panel {
    display: grid;
    gap: 10px;
    margin-bottom: 14px;
}

.httpsec-choice-grid {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 10px;
    align-items: stretch;
}

.httpsec-choice-grid-2 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}

.httpsec-choice-button {
    position: relative;
    display: grid;
    gap: 4px;
    width: 100%;
    min-height: 78px;
    padding: 14px 42px 14px 14px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--bg-depth);
    color: var(--text-main);
    text-align: left;
    cursor: pointer;
    appearance: none;
    transition: background 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.httpsec-choice-button:hover {
    background: var(--bg-card-hover);
    border-color: var(--border-strong);
}

.httpsec-choice-button.is-active {
    border-color: var(--primary);
    background: color-mix(in srgb, var(--primary) 11%, var(--bg-depth));
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--primary) 45%, transparent);
}

.httpsec-choice-button-row {
    display: flex;
    align-items: center;
    gap: 10px;
    min-height: 72px;
}

.httpsec-choice-check {
    position: absolute;
    top: 10px;
    right: 10px;
    width: 20px;
    height: 20px;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: transparent;
    background: var(--bg-elevated);
    border: 1px solid var(--border);
}

.httpsec-choice-check svg {
    width: 12px;
    height: 12px;
}

.httpsec-choice-button.is-active .httpsec-choice-check {
    color: var(--primary);
    border-color: var(--primary);
    background: var(--primary-glow);
}

.httpsec-file-types-panel {
    display: grid;
    gap: 12px;
    margin-top: 14px;
    padding: 14px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--bg-card);
}

.httpsec-file-types-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 12px;
}

.httpsec-file-type-list {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    min-height: 32px;
}

.httpsec-file-type-chip {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    min-height: 30px;
    padding: 6px 10px;
    border: 1px solid var(--border);
    border-radius: 999px;
    background: var(--bg-depth);
    color: var(--text-main);
    cursor: pointer;
    appearance: none;
}

.httpsec-file-type-chip:hover {
    border-color: var(--danger);
    background: color-mix(in srgb, var(--danger) 8%, var(--bg-depth));
}

.httpsec-file-type-chip-add:hover {
    border-color: var(--primary);
    background: color-mix(in srgb, var(--primary) 9%, var(--bg-depth));
}

.httpsec-file-type-remove {
    width: 16px;
    height: 16px;
    border-radius: 999px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    color: var(--text-muted);
    background: var(--bg-elevated);
}

.httpsec-file-type-chip:hover .httpsec-file-type-remove {
    color: var(--danger);
}

.httpsec-file-type-add {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 8px;
}

.httpsec-file-type-suggestions {
    display: grid;
    gap: 8px;
    padding-top: 10px;
    border-top: 1px solid var(--border);
}

@media (max-width: 1200px) {
    .section-module-grid,
    .grid-4 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 960px) {
    .config-page-hero {
        padding: 16px;
    }

    .config-page-hero-title {
        font-size: 19px;
    }

    .section-overview-grid,
    .section-stats-grid,
    .section-module-grid,
    .grid-3,
    .grid-2,
    .grid-2-cols,
    .grid-4 {
        grid-template-columns: 1fr;
    }

    .section-status-bar {
        align-items: flex-start;
        flex-wrap: wrap;
    }

    .section-status-right {
        margin-left: 0;
        width: 100%;
    }

    .section-managed-policy-summary {
        align-items: flex-start;
        flex-direction: column;
    }

    .section-managed-policy-meta {
        width: 100%;
        justify-content: space-between;
    }

    .feature-header {
        align-items: flex-start;
    }

    .feature-meta {
        width: 100%;
    }

    .feature-header .switch {
        margin-left: 0;
    }

    .section-control-card-head {
        flex-direction: column;
        align-items: flex-start;
    }

    .section-control-card-main {
        width: 100%;
    }

    .section-control-card-toggle {
        width: 100%;
        justify-content: space-between;
    }

    .section-control-row {
        grid-template-columns: 1fr;
    }

    .httpsec-choice-grid,
    .httpsec-choice-grid-2 {
        grid-template-columns: 1fr;
    }

    .section-inline-form {
        grid-template-columns: 1fr;
    }

    .httpsec-file-types-head,
    .httpsec-file-type-add {
        grid-template-columns: 1fr;
    }

    .httpsec-file-types-head {
        display: grid;
    }

    .section-inline-form .btn {
        justify-self: flex-start;
    }

    .httpsec-response-group-head {
        align-items: flex-start;
        flex-direction: column;
        gap: 4px;
    }

    .httpsec-simple-row {
        grid-template-columns: 1fr;
    }

    .httpsec-simple-row .section-segment-row {
        justify-content: flex-start;
    }

    .httpsec-simple-select {
        width: 100%;
        justify-self: stretch;
    }

    .httpsec-request-card .section-size-grid,
    .httpsec-check-grid {
        grid-template-columns: 1fr;
    }

    .section-config-card .feature-header>div:last-child {
        width: 100%;
        justify-content: space-between;
    }
}

/* Shared modal/dialog primitives */
.section-modal-overlay {
    position: fixed;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
}

.section-modal-overlay-padded {
    padding: 20px;
}

.section-modal-panel {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    display: flex;
    flex-direction: column;
    overflow: hidden;
    min-width: 0;
}

.section-modal-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    padding: 16px 20px;
    border-bottom: 1px solid var(--border);
}

.section-modal-title {
    margin: 0;
    font-size: 16px;
    font-weight: 600;
    color: var(--text-main);
}

.section-modal-sub {
    margin: 4px 0 0;
    font-size: 12px;
    color: var(--text-muted);
}

.section-modal-body {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 20px;
}

.section-modal-footer {
    padding: 16px 20px;
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 10px;
}

.section-confirm-modal {
    width: min(460px, calc(100vw - 32px));
    border-radius: var(--radius-lg);
    overflow: hidden;
}

.section-confirm-head {
    display: grid;
    grid-template-columns: 42px minmax(0, 1fr) 34px;
    align-items: center;
    gap: 12px;
    padding: 18px 20px 16px;
    border-bottom: 1px solid var(--border);
    background: var(--bg-card);
}

.section-confirm-head.is-danger {
    background: linear-gradient(180deg, color-mix(in srgb, var(--section-confirm-accent, var(--danger)) 10%, transparent), var(--bg-card));
}

.section-confirm-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 42px;
    height: 42px;
    color: var(--section-confirm-accent, var(--warning));
    background: color-mix(in srgb, var(--section-confirm-accent, var(--warning)) 12%, transparent);
    border: 1px solid color-mix(in srgb, var(--section-confirm-accent, var(--warning)) 35%, transparent);
    border-radius: var(--radius);
}

.section-confirm-icon svg,
.section-confirm-close svg {
    display: block;
}

.section-confirm-title-block {
    min-width: 0;
}

.section-confirm-title {
    margin: 0;
    color: var(--text-main);
    font-size: 17px;
    line-height: 1.25;
    font-weight: 700;
}

.section-confirm-sub {
    margin: 4px 0 0;
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.35;
}

.section-confirm-close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 34px;
    height: 34px;
    padding: 0;
    color: var(--text-muted);
    background: transparent;
    border: 0;
    border-radius: var(--radius);
    cursor: pointer;
}

.section-confirm-close:hover,
.section-confirm-close:focus-visible {
    color: var(--text-main);
    background: var(--glass-highlight);
}

.section-confirm-body {
    padding: 18px 20px;
}

.section-confirm-message {
    color: var(--text-muted);
    font-size: 13px;
    line-height: 1.55;
}

.section-confirm-message p {
    margin: 10px 0 0;
}

.section-confirm-rule-name {
    display: block;
    max-width: 100%;
    padding: 10px 12px;
    color: var(--text-main);
    background: var(--bg-depth);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    font-size: 13px;
    line-height: 1.35;
    font-weight: 700;
    overflow-wrap: anywhere;
}

.section-confirm-footer {
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 10px;
    padding: 14px 20px;
    border-top: 1px solid var(--border);
    background: var(--bg-depth);
}

.section-confirm-primary.is-danger {
    color: #fff;
    background: var(--section-confirm-accent, var(--danger));
    border-color: var(--section-confirm-accent, var(--danger));
}

.section-confirm-primary.is-danger:hover,
.section-confirm-primary.is-danger:focus-visible {
    filter: brightness(0.94);
}

.section-confirm-primary[disabled] {
    opacity: 0.65;
    cursor: wait;
}

/* WAF section: shared layout primitives */
.section-status-bar {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 18px;
    background: var(--bg-depth);
    border-radius: var(--radius-lg);
    margin-bottom: 24px;
}

.section-header {
    border-left: 4px solid var(--primary);
}

.section-header-icon {
    padding: 12px;
    background: var(--primary-muted);
    color: var(--primary);
}

.section-header-title {
    margin: 0;
}

.section-header-sub {
    margin-top: 4px;
}

.section-status-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--text-dim);
}

.section-status-dot.is-active {
    background: var(--success);
}

.section-status-dot.is-inactive {
    background: var(--text-dim);
}

.section-status-dot.success {
    background: var(--success);
}

.section-status-dot.danger {
    background: var(--danger);
}

.section-status-title {
    font-weight: 600;
    font-size: 14px;
}

.section-status-divider {
    color: var(--text-dim);
}

.section-status-meta {
    color: var(--text-muted);
    font-size: 13px;
}

.section-security-score.good {
    color: var(--success);
}

/* =============================================================================
   ADMIN UI SIMPLIFICATION
   Flatten section screens and keep configuration surfaces attached
   ============================================================================= */

.section-config-container {
    padding: 18px 20px 24px;
    background: var(--bg-void);
}

.config-page-hero {
    margin-bottom: 16px;
    padding: 16px 18px;
    border-radius: var(--radius-lg);
    background: var(--bg-card);
    box-shadow: none;
}

.config-page-hero-kicker {
    color: var(--text-dim);
}

.config-page-hero-title {
    font-size: 20px;
}

.config-page-hero-subtitle {
    margin-top: 6px;
    color: var(--text-muted);
}

.config-page-hero-actions {
    margin-top: 2px;
}

.section-tab-row {
    margin-bottom: 14px;
    padding: 4px;
    border-radius: var(--radius-lg);
    background: var(--bg-panel);
    box-shadow: none;
}

.section-tab-btn.btn-primary,
.section-tab-btn.active,
.section-tab-btn.is-active {
    background: color-mix(in srgb, var(--primary) 14%, var(--bg-interactive)) !important;
    border-color: color-mix(in srgb, var(--primary) 20%, var(--border)) !important;
    color: var(--text-main) !important;
}

.section-tab-btn.btn-primary svg,
.section-tab-btn.active svg,
.section-tab-btn.is-active svg {
    color: var(--primary);
}

.section-hero-shell {
    margin-bottom: 18px;
}

.section-status-bar {
    padding: 12px 16px;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius-lg);
    margin-bottom: 18px;
}

.section-metric-card,
.section-control-card {
    background: var(--bg-card);
    border-radius: var(--radius-lg);
    box-shadow: none;
}

.section-metric-card {
    padding: 14px 16px;
}

.section-control-card-head,
.section-control-card-body {
    padding-left: 14px;
    padding-right: 14px;
}

.section-control-card-icon {
    border-radius: var(--radius-lg);
    background: var(--primary-glow);
}

.toggle-card {
    background: var(--bg-card);
}

.toggle-card.active {
    border-color: color-mix(in srgb, var(--success) 55%, var(--border));
}

.section-header {
    border-left: 0;
}

.section-header-icon {
    padding: 10px;
    border-radius: var(--radius-lg);
    background: var(--primary-glow);
}

.section-btn-table:hover,
.section-btn-table:focus-visible {
    background: var(--glass-highlight);
    border-color: var(--border-strong);
    color: var(--text-main);
}

.section-btn-table-danger:hover,
.section-btn-table-danger:focus-visible {
    background: var(--status-danger-bg);
    border-color: color-mix(in srgb, var(--danger) 60%, var(--border));
    color: var(--danger);
}

.section-security-score.warn {
    color: var(--warning);
}

.section-status-mode {
    color: var(--text-dim);
}

.section-status-mode.mode-blocking {
    color: var(--danger);
}

.section-status-mode.mode-detection {
    color: var(--primary);
}

.section-status-mode.mode-off {
    color: var(--text-dim);
}

.section-status-right {
    margin-left: auto;
    display: flex;
    align-items: center;
    gap: 12px;
}

.section-status-label {
    font-size: 12px;
    color: var(--text-dim);
    text-transform: uppercase;
    font-weight: 600;
}

.section-state-pill {
    padding: 4px 8px;
    border-radius: 4px;
    font-size: 11px;
    font-weight: 600;
}

.section-state-pill.is-running {
    background: var(--status-success-bg);
    color: var(--success);
}

.section-state-pill.is-stopped {
    background: var(--status-danger-bg);
    color: var(--danger);
}

.section-metrics-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 16px;
    margin-bottom: 32px;
}

.section-metric-card {
    padding: 24px;
    position: relative;
    overflow: hidden;
    border: 1px solid var(--border);
}

.section-metric-icon {
    position: absolute;
    top: 0;
    right: 0;
    padding: 16px;
    opacity: 0.05;
    color: var(--text-main);
    font-size: 48px;
    transform: rotate(15deg);
}

.section-metric-icon.tone-neutral {
    color: var(--text-main);
}

.section-metric-icon.tone-danger {
    color: var(--danger);
}

.section-metric-icon.tone-info {
    color: var(--info);
}

.section-metric-icon.tone-success {
    color: var(--success);
}

.section-metric-label {
    font-size: 11px;
    text-transform: uppercase;
    color: var(--text-muted);
    font-weight: 700;
    letter-spacing: 0.8px;
    margin-bottom: 12px;
}

.section-metric-value {
    font-size: 32px;
    font-weight: 700;
    color: var(--text);
    line-height: 1;
    letter-spacing: -0.5px;
}

.section-metric-unit {
    font-size: 16px;
    color: var(--text-muted);
    font-weight: 500;
    margin-left: 2px;
}

.section-metric-sub {
    font-size: 12px;
    color: var(--text-dim);
    margin-top: 8px;
    display: flex;
    align-items: center;
    gap: 6px;
    font-weight: 400;
}

.section-metric-sub.is-bold {
    font-weight: 500;
}

.section-metric-sub.is-danger {
    color: var(--danger);
}

.section-metric-sub.is-success {
    color: var(--success);
}

.section-metric-sub.is-muted {
    color: var(--text-dim);
}

.section-metric-sub-dot {
    display: inline-block;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--section-sub-dot, var(--primary));
}

.section-chart-empty {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: var(--text-muted);
    background: var(--bg-depth);
    border-radius: var(--radius-lg);
}

.section-chart-svg {
    width: 100%;
    height: 100%;
}

.section-main-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 24px;
}

.section-col-stack {
    display: flex;
    flex-direction: column;
    gap: 24px;
