    border-radius: var(--radius-sm);
    background: var(--input-bg);
    color: var(--text-main);
}

.edge-paranoia-warning div {
    display: grid;
    gap: 4px;
    min-width: 0;
}

.edge-paranoia-warning strong {
    color: var(--brand-orange);
    font-size: 12px;
    font-weight: 800;
}

.edge-paranoia-warning span {
