    border-radius: 8px;
    background: var(--bg-depth);
}

.leak-noise-grid {
    display: grid;
    gap: 10px;
}

.leak-noise-grid > div {
    display: grid;
    gap: 4px;
    padding: 10px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--bg-depth);
}

.leak-noise-grid span,
.leak-noise-grid small {
    color: var(--text-muted);
    font-size: 11px;
    line-height: 1.35;
}

.leak-noise-grid span {
    font-weight: 750;
    text-transform: uppercase;
}

.leak-noise-grid strong {
    color: var(--text-main);
    font-size: 15px;
    overflow-wrap: anywhere;
}

.leak-sim-warnings {
    display: grid;
    gap: 8px;
}

.leak-sim-warning {
    display: grid;
    gap: 3px;
    padding: 10px 12px;
    border: 1px solid var(--border);
    border-radius: 8px;
    background: var(--bg-depth);
}

.leak-sim-warning.tone-warning {
    border-color: color-mix(in srgb, var(--warning) 48%, var(--border));
}

.leak-sim-warning.tone-info {
    border-color: color-mix(in srgb, var(--primary) 36%, var(--border));
}

.leak-sim-warning strong {
    color: var(--text-main);
    font-size: 13px;
}

.leak-sim-warning span {
    color: var(--text-muted);
    font-size: 12px;
    line-height: 1.4;
}

.aux-config-grid .section-config-panel,
.aux-panel {
    border-radius: 8px;
}

@media (max-width: 960px) {
    .section-config-grid,
    .bot-overview-field-grid,
    .leak-workspace,
    .leak-pack-grid,
    .leak-summary-grid,
    .leak-status-strip,
    .leak-rollout-rail {
        grid-template-columns: 1fr;
    }

    .leak-command,
    .aux-command-head {
        align-items: flex-start;
        flex-direction: column;
    }
}

