    align-items: center;
    justify-content: center;
    border: 1px solid rgba(255, 255, 255, 0.12);
    background: rgba(15, 23, 42, 0.82);
    color: #f1f5f9;
    font-size: 16px;
    font-weight: 500;
    line-height: 1;
