    flex: 1 1 auto;
    min-height: 0;
    max-height: none;
    border: 0;
    border-radius: 0;
    background: var(--operator-surface, #ffffff);
    overflow-y: scroll;
    overscroll-behavior: contain;
    scrollbar-gutter: stable;
}

